        try:self.wfile.write(body)
        except OSError:pass


with nginx() as p:
    master=int(pathlib.Path('nginx.pid').read_text())
    def workers():return [int(v) for v in pathlib.Path(f'/proc/{master}/task/{master}/children').read_text().split()]
    for cycle in range(2):
        deadline=time.monotonic()+2
        while not workers() and time.monotonic()<deadline:time.sleep(.01)
        previous=workers();assert len(previous)==1 and previous[0]!=master,previous
        assert request(p)[0:2]==(200,b'worker alive')
        os.kill(previous[0],signal.SIGTERM);deadline=time.monotonic()+2
        while time.monotonic()<deadline:
            current=workers()
